class ConfigurableClock {
  constructor() { this.instant = 0; this.fail = false; }
  now() {
    if (this.fail) throw new Error('clock unavailable');
    return this.instant;
  }
}

const clock = Object.assign(new ConfigurableClock(), { instant: epoch, fail: true });
